// =============================================================
// 1. ELEMEN DOM & VARIABEL UTAMA
// =============================================================
const videoElement = document.getElementById('webcam');
const canvasElement = document.getElementById('output_canvas');
const canvasCtx = canvasElement.getContext('2d');
const gestureName = document.getElementById('gesture-name');
const btnPopup = document.getElementById('btn-popup');

let popupWindow = null;
let currentTextState = null;

let scene, camera3D, renderer3D, particleSystem, particleMaterial;
let currentPositions, targetPositions;
let targetX = 0, targetY = 0;
let lastKey = null;
const PARTICLE_COUNT = 3000;
let shapes = {};

// Variabel Tambahan Gambar
let imageMesh;
const textureLoader = new THREE.TextureLoader();
const loadedTextures = {};

const imageUrls = {
  ABSOLUTECINEMA: 'data:image/png;base64,'
};

Object.keys(imageUrls).forEach((key) => {
  textureLoader.load(
    imageUrls[key],
    (tex) => {
      loadedTextures[key] = tex;
    },
    undefined,
    (err) => {
      console.error(`Gagal memuat gambar ${key}:`, err);
    }
  );
});

// =============================================================
// 2. GENERATOR BENTUK PARTIKEL 3D
// =============================================================

function generateTextPoints(text, scaleFactor = 0.45) {
  const c = document.createElement('canvas');
  c.width = 600; 
  c.height = 150;
  const cx = c.getContext('2d');
  
  cx.font = 'Bold 32px sans-serif';
  cx.fillStyle = '#ffffff';
  cx.textAlign = 'center';
  cx.textBaseline = 'middle';
  cx.fillText(text, 300, 75);

  const imgData = cx.getImageData(0, 0, 600, 150);
  const validPixels = [];
  
  for (let y = 0; y < 150; y += 2) {
    for (let x = 0; x < 600; x += 2) {
      if (imgData.data[(y * 600 + x) * 4 + 3] > 128) {
        validPixels.push({
          x: (x - 300) * scaleFactor,
          y: -(y - 75) * scaleFactor,
          z: (Math.random() - 0.5) * 10
        });
      }
    }
  }

  const points = [];
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const p = validPixels[i % validPixels.length];
    points.push(p.x, p.y, p.z);
  }
  return points;
}

function generateHeartPoints() {
  const points = [];
  const scale = 7.5;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const t = Math.random() * Math.PI * 2;
    const x = 16 * Math.pow(Math.sin(t), 3);
    const y = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
    
    const fillFactor = Math.sqrt(Math.random()); 
    const px = x * scale * fillFactor;
    const py = y * scale * fillFactor;
    const pz = (Math.random() - 0.5) * 20;

    points.push(px, py, pz);
  }
  return points;
}

function generateTrianglePoints() {
  const points = [];
  const size = 120;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    let r1 = Math.random();
    let r2 = Math.random();
    if (r1 + r2 > 1) {
      r1 = 1 - r1;
      r2 = 1 - r2;
    }
    const A = { x: 0, y: size };
    const B = { x: -size, y: -size / 1.5 };
    const C = { x: size, y: -size / 1.5 };

    const x = A.x + r1 * (B.x - A.x) + r2 * (C.x - A.x);
    const y = A.y + r1 * (B.y - A.y) + r2 * (C.y - A.y);
    const z = (Math.random() - 0.5) * 15;

    points.push(x, y, z);
  }
  return points;
}

function generateSquarePoints() {
  const points = [];
  const size = 180;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const x = (Math.random() - 0.5) * size;
    const y = (Math.random() - 0.5) * size;
    const z = (Math.random() - 0.5) * 15;
    points.push(x, y, z);
  }
  return points;
}

function generateCirclePoints() {
  const points = [];
  const radius = 100;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r = Math.sqrt(Math.random()) * radius;
    const x = r * Math.cos(angle);
    const y = r * Math.sin(angle);
    const z = (Math.random() - 0.5) * 15;
    points.push(x, y, z);
  }
  return points;
}

// =============================================================
// 3. INISIALISASI SCENE & RENDERER THREE.JS (POPUP)
// =============================================================

function initThreeJSInPopup(popupDoc) {
  const canvas3D = popupDoc.getElementById('popup_canvas');

  scene = new THREE.Scene();
  camera3D = new THREE.PerspectiveCamera(45, popupWindow.innerWidth / popupWindow.innerHeight, 0.1, 1000);
  camera3D.position.z = 400;

  renderer3D = new THREE.WebGLRenderer({ canvas: canvas3D, alpha: true, antialias: true });
  renderer3D.setSize(popupWindow.innerWidth, popupWindow.innerHeight);

  const geometry = new THREE.BufferGeometry();
  currentPositions = new Float32Array(PARTICLE_COUNT * 3);
  targetPositions = new Float32Array(PARTICLE_COUNT * 3);

  for (let i = 0; i < PARTICLE_COUNT * 3; i++) {
    currentPositions[i] = (Math.random() - 0.5) * 400;
    targetPositions[i] = currentPositions[i];
  }
  geometry.setAttribute('position', new THREE.BufferAttribute(currentPositions, 3));

  const canvasP = document.createElement('canvas');
  canvasP.width = 16; 
  canvasP.height = 16;
  const ctxP = canvasP.getContext('2d');
  const grad = ctxP.createRadialGradient(8, 8, 0, 8, 8, 8);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctxP.fillStyle = grad;
  ctxP.fillRect(0, 0, 16, 16);

  const particleTexture = new THREE.CanvasTexture(canvasP);
  particleMaterial = new THREE.PointsMaterial({
    color: 0x38bdf8,
    size: 7,
    map: particleTexture,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });

  particleSystem = new THREE.Points(geometry, particleMaterial);
  scene.add(particleSystem);

  const imgGeometry = new THREE.PlaneGeometry(260, 260);
  const imgMaterial = new THREE.MeshBasicMaterial({
    transparent: true,
    opacity: 0,
    depthTest: false
  });
  imageMesh = new THREE.Mesh(imgGeometry, imgMaterial);
  scene.add(imageMesh);

  imageMesh.renderOrder = 0;
  particleSystem.renderOrder = 1;

  imageMesh.position.z = -20; 
  
  shapes = {
    TRIANGLE: generateTrianglePoints(),
    SQUARE: generateSquarePoints(),
    CIRCLE: generateCirclePoints(),
    HEART: generateHeartPoints(),
    MEANDYOU: generateTextPoints("ME & YOU", 0.55),
    ABSOLUTECINEMA: []
  };

  animate3D();

  popupWindow.addEventListener('resize', () => {
    if (camera3D && renderer3D) {
      camera3D.aspect = popupWindow.innerWidth / popupWindow.innerHeight;
      camera3D.updateProjectionMatrix();
      renderer3D.setSize(popupWindow.innerWidth, popupWindow.innerHeight);
    }
  });
}

function animate3D() {
  if (!popupWindow || popupWindow.closed) return;

  popupWindow.requestAnimationFrame(animate3D);

  const pos = particleSystem.geometry.attributes.position.array;
  for (let i = 0; i < PARTICLE_COUNT * 3; i += 3) {
    pos[i]     += (targetPositions[i] - pos[i]) * 0.08;
    pos[i + 1] += (targetPositions[i + 1] - pos[i + 1]) * 0.08;
    pos[i + 2] += (targetPositions[i + 2] - pos[i + 2]) * 0.08;
  }
  particleSystem.geometry.attributes.position.needsUpdate = true;

  particleSystem.position.x += (targetX - particleSystem.position.x) * 0.1;
  particleSystem.position.y += (targetY - particleSystem.position.y) * 0.1;
  
  particleSystem.rotation.y = 0;

  renderer3D.render(scene, camera3D);
}

function openPopupWindow() {
  if (!popupWindow || popupWindow.closed) {
    popupWindow = window.open('', 'Gesture3DPopup', 'width=600,height=600,resizable=yes');
    
    const doc = popupWindow.document;
    doc.open();
    doc.write(`
      <!DOCTYPE html>
      <html lang="id">
      <head>
        <meta charset="UTF-8">
        <title>Gesture Visualizer 3D</title>
        <link rel="stylesheet" href="style.css">
        <style>
          html, body {
            background-color: #000000 !important;
          }
        </style>
      </head>
      <body class="popup-body">
        <div id="text-display">Menunggu Gestur...</div>
        <canvas id="popup_canvas"></canvas>
      </body>
      </html>
    `);
    doc.close();

    setTimeout(() => {
      initThreeJSInPopup(doc);
    }, 100);
  } else {
    popupWindow.focus();
  }
}

btnPopup.addEventListener('click', openPopupWindow);

// =============================================================
// KUMPULAN EFEK SUARA GESTUR
// =============================================================
const gestureSounds = {
  TRIANGLE: new Audio('sounds/triangle.mp3'),
  SQUARE: new Audio('sounds/square.mp3'),
  CIRCLE: new Audio('sounds/circle.mp3'),
  HEART: new Audio('sounds/heart.mp3'),
  MEANDYOU: new Audio('sounds/meandyou.mp3'),
  ABSOLUTECINEMA: new Audio('sound/absolute-cinema-meme.mp3') 
};

let lastPlayedGesture = null; 

function playGestureSound(shapeKey) {
  if (lastPlayedGesture !== shapeKey) {
    if (gestureSounds[shapeKey]) {
      gestureSounds[shapeKey].currentTime = 0; 
      gestureSounds[shapeKey].play().catch(err => {
        console.warn("Autoplay terblokir atau file audio tidak ditemukan:", err);
      });
    }
    lastPlayedGesture = shapeKey;
  }
} 

// =============================================================
// 4. KONTROL GESTUR & UPDATE EVENT
// =============================================================

function updatePopupShape(shapeKey, colorHex, labelText, midX, midY) {
  if (popupWindow && !popupWindow.closed && particleMaterial) {

    playGestureSound(shapeKey);

    const textDisplay = popupWindow.document.getElementById('text-display');
    if (textDisplay) {
      if (shapeKey === "ABSOLUTECINEMA") {
        textDisplay.innerText = ""; 
      } else {
        textDisplay.innerText = labelText;
        textDisplay.style.color = `#${colorHex.toString(16).padStart(6, '0')}`;
      }
    }

    particleMaterial.color.setHex(colorHex);

    if (imageMesh) {
      if (loadedTextures[shapeKey]) {
        imageMesh.material.map = loadedTextures[shapeKey];
        imageMesh.material.opacity = 1.0; 
        imageMesh.material.needsUpdate = true;
        imageMesh.visible = true;
      } else {
        imageMesh.visible = false; 
      }
    }

    if (lastKey !== shapeKey) {
      const targetPoints = shapes[shapeKey] || [];
      
      for (let i = 0; i < PARTICLE_COUNT * 3; i++) {
        targetPositions[i] = targetPoints[i] !== undefined ? targetPoints[i] : 0;
      }
      lastKey = shapeKey;
    }

    if (midX !== undefined && midY !== undefined) {
      const normX = -((midX) * 2 - 1);
      const normY = -((midY) * 2 - 1);
      targetX = normX * 180;
      targetY = normY * 120;
      
      if (imageMesh) {
        imageMesh.position.x = targetX;
        imageMesh.position.y = targetY;
        imageMesh.position.z = 0; 
      }
    }
  }
}

function distance(p1, p2) {
  return Math.hypot(p1.x - p2.x, p1.y - p2.y);
}

function getHandGesture(landmarks) {
  const wrist = landmarks[0];

  const isIndexUp  = distance(landmarks[8], wrist) > distance(landmarks[5], wrist);
  const isMiddleUp = distance(landmarks[12], wrist) > distance(landmarks[9], wrist);
  const isRingUp   = distance(landmarks[16], wrist) > distance(landmarks[13], wrist);
  const isPinkyUp  = distance(landmarks[20], wrist) > distance(landmarks[17], wrist);

  if (isIndexUp && !isMiddleUp && !isRingUp && !isPinkyUp) return "INDEX";
  if (isIndexUp && isMiddleUp && !isRingUp && !isPinkyUp) return "PEACE";
  if (!isIndexUp && !isMiddleUp && !isRingUp && !isPinkyUp) return "FIST"; 
  if (isIndexUp && isMiddleUp && isRingUp && isPinkyUp) return "OPEN";
  
  return "OTHER";
}

function onResults(results) {
  canvasCtx.save();
  canvasCtx.clearRect(0, 0, canvasElement.width, canvasElement.height);

  const handsDetected = results.multiHandLandmarks ? results.multiHandLandmarks.length : 0;

  if (handsDetected > 0) {
    openPopupWindow();

    if (handsDetected === 2) {
      const g1 = getHandGesture(results.multiHandLandmarks[0]);
      const g2 = getHandGesture(results.multiHandLandmarks[1]);
      
      const midX = (results.multiHandLandmarks[0][0].x + results.multiHandLandmarks[1][0].x) / 2;
      const midY = (results.multiHandLandmarks[0][0].y + results.multiHandLandmarks[1][0].y) / 2;

      if (g1 === "OPEN" && g2 === "OPEN") {
        gestureName.innerText = "✋ + ✋ 2 Tangan Terbuka: \"ABSOLUTE CINEMA\"";
        gestureName.style.color = "#eab308";
        updatePopupShape("ABSOLUTECINEMA", 0xeab308, "Teks: \"ABSOLUTE CINEMA\"", midX, midY);
      } 
      else if (g1 === "FIST" && g2 === "FIST") {
        gestureName.innerText = "🫶 2 Tangan Mengepal: LOVE ❤️";
        gestureName.style.color = "#f43f5e";
        updatePopupShape("HEART", 0xf43f5e, "Bentuk: Hati ❤️", midX, midY);
      } 
      else {
        gestureName.innerText = "Kombinasi 2 Tangan Belum Cocok";
        gestureName.style.color = "#eab308";
      }
    } 
    else if (handsDetected === 1) {
      const hand = results.multiHandLandmarks[0];
      const gesture = getHandGesture(hand);
      const posX = hand[0].x;
      const posY = hand[0].y;

      if (gesture === "INDEX") {
        gestureName.innerText = "👆 1 Tangan (Telunjuk): Segitiga 🔺";
        gestureName.style.color = "#38bdf8";
        updatePopupShape("TRIANGLE", 0x38bdf8, "Bentuk: Segitiga 🔺", posX, posY);
      } else if (gesture === "PEACE") {
        gestureName.innerText = "✌️ 1 Tangan (2 Jari/Peace): \"ME & YOU\"";
        gestureName.style.color = "#a855f7";
        updatePopupShape("MEANDYOU", 0xa855f7, "Teks: \"ME & YOU\"", posX, posY);
      } else if (gesture === "FIST") {
        gestureName.innerText = "✊ 1 Tangan (Mengepal): Persegi ⬛";
        gestureName.style.color = "#ec4899";
        updatePopupShape("SQUARE", 0xec4899, "Bentuk: Persegi ⬛", posX, posY);
      } else if (gesture === "OPEN") {
        gestureName.innerText = "✋ 1 Tangan Terbuka: Lingkaran 🔴";
        gestureName.style.color = "#22c55e";
        updatePopupShape("CIRCLE", 0x22c55e, "Bentuk: Lingkaran 🔴", posX, posY);
      } else {
        gestureName.innerText = "Gestur Tangan Tidak Dikenali";
        gestureName.style.color = "#eab308";
      }
    }

  } else {
    gestureName.innerText = "Arahkan Tangan ke Kamera";
    gestureName.style.color = "#eab308";
    currentTextState = null;

    hasPlayedCinemaSound = false;
  }

  canvasCtx.restore();
}

// Inisialisasi MediaPipe Hands & Camera
const hands = new Hands({
  locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`
});

hands.setOptions({
  maxNumHands: 2,
  modelComplexity: 1,
  minDetectionConfidence: 0.7,
  minTrackingConfidence: 0.7
});

hands.onResults(onResults);

const camera = new Camera(videoElement, {
  onFrame: async () => {
    await hands.send({ image: videoElement });
  },
  width: 640,
  height: 480
});

camera.start();